CREATE UNIQUE INDEX uq_platform_acquisition_scripts_code ON platform_acquisition_scripts (tenant_id, script_code);

CREATE TABLE platform_data_artifacts (
  artifact_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  tenant_id CHAR(36) NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  artifact_key VARCHAR(160) NOT NULL,
  artifact_type VARCHAR(32) NOT NULL CHECK (artifact_type IN ('csv','parquet','json','image','chart','export','document','other')),
  object_uri VARCHAR(512) NOT NULL,
  content_hash CHAR(64) NOT NULL,
  content_type VARCHAR(200) NOT NULL,
  size_bytes BIGINT NOT NULL CHECK (size_bytes >= 0),
