CREATE TABLE platform_memory_records (
  memory_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  tenant_id CHAR(36) NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  memory_key VARCHAR(160) NOT NULL,
