CREATE INDEX idx_platform_memory_hash ON platform_memory_records (tenant_id, content_hash);

CREATE TABLE platform_analysis_tasks (
  analysis_task_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  tenant_id CHAR(36) NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  task_key VARCHAR(100) NOT NULL UNIQUE,
