  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='OpenTelemetry 兼容的父子 Span、耗时和资源属性。';
