CREATE INDEX idx_platform_runtime_events_type ON platform_runtime_events (tenant_id, event_type, occurred_at);

CREATE TABLE platform_automation_tasks (
  automation_task_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
