  rule_domain VARCHAR(32) NOT NULL CHECK (rule_domain IN ('data_quality','freshness','metric','job','system','security','market')),
  condition_expression JSON NOT NULL,
  severity VARCHAR(16) NOT NULL CHECK (severity IN ('info','warning','error','critical')),
  cooldown_seconds INTEGER NOT NULL DEFAULT 300 CHECK (cooldown_seconds >= 0),
  notification_policy JSON NOT NULL DEFAULT (JSON_OBJECT()),
  status VARCHAR(24) NOT NULL DEFAULT 'active' CHECK (status IN ('draft','active','paused','disabled')),
  created_by CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='数据、任务、指标和系统异常的统一告警规则。';
CREATE INDEX idx_platform_alert_rules_tenant_updated ON platform_alert_rules (tenant_id, updated_at, alert_rule_id);
CREATE UNIQUE INDEX uq_platform_alert_rules_code ON platform_alert_rules (tenant_id, rule_code);
CREATE INDEX idx_platform_alert_rules_status ON platform_alert_rules (tenant_id, status);

CREATE TABLE platform_subscriptions (
  subscription_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  tenant_id CHAR(36) NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  subscription_key VARCHAR(160) NOT NULL,
  subscriber_user_id CHAR(36) NOT NULL REFERENCES platform_user_profiles(user_id) ON DELETE CASCADE,
  subscription_name VARCHAR(300) NOT NULL,
  event_types JSON NOT NULL DEFAULT (JSON_ARRAY()),
  channel_type VARCHAR(24) NOT NULL CHECK (channel_type IN ('in_app','email','webhook','feishu','wecom','sms')),
  channel_config_cipher LONGBLOB NOT NULL,
  filter_expression JSON NOT NULL DEFAULT (JSON_OBJECT()),
  quiet_hours JSON NOT NULL DEFAULT (JSON_OBJECT()),
  subscription_type VARCHAR(32) NOT NULL DEFAULT 'task' CHECK (subscription_type IN ('report','metric','alert','market','task')),
  resource_id CHAR(36),
  filter_config JSON NOT NULL DEFAULT (JSON_OBJECT()),
  channels JSON NOT NULL,
  schedule_config JSON NOT NULL DEFAULT (JSON_OBJECT()),
  status VARCHAR(24) NOT NULL DEFAULT 'active' CHECK (status IN ('active','paused','disabled')),
  disabled_at DATETIME(6),
  created_by CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户对报告、指标、告警和市场事件的推送订阅。';
CREATE INDEX idx_platform_subscriptions_tenant_updated ON platform_subscriptions (tenant_id, updated_at, subscription_id);
CREATE UNIQUE INDEX uq_platform_subscriptions_key ON platform_subscriptions (tenant_id, subscription_key);
CREATE INDEX idx_platform_subscriptions_user ON platform_subscriptions (tenant_id, subscriber_user_id, status);

CREATE TABLE platform_provider_callbacks (
  callback_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  tenant_id CHAR(36) NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  callback_key VARCHAR(160) NOT NULL,
  provider VARCHAR(80) NOT NULL,
  provider_event_id VARCHAR(300) NOT NULL,
  provider_message_id VARCHAR(300),
  event_type VARCHAR(100) NOT NULL,
  signature_valid BOOLEAN NOT NULL,
  payload_hash CHAR(64) NOT NULL,
  safe_payload JSON NOT NULL DEFAULT (JSON_OBJECT()),
  processed_at DATETIME(6),
  processing_status VARCHAR(24) NOT NULL DEFAULT 'pending' CHECK (processing_status IN ('pending','processed','ignored','failed')),
  created_by CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='邮件、飞书、企微等渠道回调的幂等原始事件摘要。';
CREATE INDEX idx_platform_provider_callbacks_tenant_updated ON platform_provider_callbacks (tenant_id, updated_at, callback_id);
CREATE UNIQUE INDEX uq_platform_provider_callbacks ON platform_provider_callbacks (provider, provider_event_id);
CREATE INDEX idx_platform_provider_callbacks_pending ON platform_provider_callbacks (processing_status, created_at);

CREATE TABLE platform_application_module_state (
  module_state_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  tenant_id CHAR(36) NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  module_code VARCHAR(160) NOT NULL,
  owner_user_id CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE CASCADE,
  state_key VARCHAR(200) NOT NULL,
  state_value JSON NOT NULL,
  state_schema_version INTEGER NOT NULL DEFAULT 1 CHECK (state_schema_version > 0),
  created_by CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='现有页面非核心 UI 状态的服务端持久化兼容层。';
CREATE INDEX idx_platform_application_module_state_tenant_updated ON platform_application_module_state (tenant_id, updated_at, module_state_id);
CREATE UNIQUE INDEX uq_platform_application_module_state ON platform_application_module_state (tenant_id, module_code, ((COALESCE(owner_user_id, '00000000-0000-0000-0000-000000000000'))), state_key);

CREATE TABLE platform_application_actions (
  application_action_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  tenant_id CHAR(36) NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  application_action_key VARCHAR(160) NOT NULL,
  module_code VARCHAR(160) NOT NULL,
  action_code VARCHAR(160) NOT NULL,
  actor_user_id CHAR(36) NOT NULL REFERENCES platform_user_profiles(user_id) ON DELETE RESTRICT,
  idempotency_key VARCHAR(200) NOT NULL,
  request_payload JSON NOT NULL DEFAULT (JSON_OBJECT()),
  status VARCHAR(24) NOT NULL CHECK (status IN ('accepted','running','succeeded','failed','rejected')),
  handler_ref VARCHAR(300) NOT NULL,
  result_ref JSON NOT NULL DEFAULT (JSON_OBJECT()),
  error_code VARCHAR(100),
  finished_at DATETIME(6),
  created_by CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='已注册页面动作的命令记录和真实 handler 结果。';
CREATE INDEX idx_platform_application_actions_tenant_updated ON platform_application_actions (tenant_id, updated_at, application_action_id);
CREATE UNIQUE INDEX uq_platform_application_action_key ON platform_application_actions (tenant_id, application_action_key);
CREATE UNIQUE INDEX uq_platform_application_actions_idempotency ON platform_application_actions (tenant_id, module_code, action_code, idempotency_key);
CREATE INDEX idx_platform_application_actions_actor ON platform_application_actions (tenant_id, actor_user_id, created_at);

CREATE TABLE platform_bridge_bindings (
  binding_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  binding_key VARCHAR(160) NOT NULL UNIQUE,
  token_hash CHAR(64) NOT NULL UNIQUE,
  channel VARCHAR(32) NOT NULL CHECK (channel IN ('workbuddy','codex','qwork')),
  tenant_id CHAR(36) NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  user_id CHAR(36) NOT NULL REFERENCES platform_user_profiles(user_id) ON DELETE CASCADE,
  visibility VARCHAR(16) NOT NULL DEFAULT 'private' CHECK (visibility IN ('private','tenant')),
  display_label VARCHAR(120) NOT NULL,
  device_name VARCHAR(160) NOT NULL,
  created_at_epoch BIGINT NOT NULL,
  revoked_at_epoch BIGINT,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='WorkBuddy、Codex、QWork 一次点击授权形成的可撤销 Bridge 设备绑定；只保存令牌哈希。';
CREATE INDEX idx_platform_bridge_bindings_owner ON platform_bridge_bindings (tenant_id, user_id, channel, revoked_at_epoch);

CREATE TABLE platform_analysis_workspaces (
  workspace_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
