  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='从 MCP Server 同步并授权的工具目录。';
CREATE INDEX idx_platform_mcp_tools_tenant_updated ON platform_mcp_tools (tenant_id, updated_at, mcp_tool_id);
CREATE UNIQUE INDEX uq_platform_mcp_tools_name ON platform_mcp_tools (mcp_server_id, tool_name);

CREATE TABLE platform_model_calls (
  model_call_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  tenant_id CHAR(36) NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  model_call_key VARCHAR(300) NOT NULL UNIQUE,
  analysis_task_id CHAR(36),
  subject_type VARCHAR(64) NOT NULL DEFAULT 'analysis_task',
  subject_id VARCHAR(300) NOT NULL,
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision > 0),
  model_integration_id CHAR(36) NOT NULL REFERENCES platform_model_integrations(model_integration_id) ON DELETE RESTRICT,
  provider_model_name VARCHAR(200) NOT NULL DEFAULT '',
  prompt_template_id CHAR(36) REFERENCES platform_prompt_templates(prompt_template_id) ON DELETE SET NULL,
  request_hash CHAR(64) NOT NULL,
  response_hash CHAR(64),
  status VARCHAR(24) NOT NULL CHECK (status IN ('queued','running','succeeded','degraded','failed','cancelled')),
  input_tokens INTEGER NOT NULL DEFAULT 0 CHECK (input_tokens >= 0),
  output_tokens INTEGER NOT NULL DEFAULT 0 CHECK (output_tokens >= 0),
  usage_source VARCHAR(24) NOT NULL DEFAULT 'estimated' CHECK (usage_source IN ('provider','estimated')),
  cost_amount NUMERIC(18,6) NOT NULL DEFAULT 0 CHECK (cost_amount >= 0),
  latency_ms INTEGER CHECK (latency_ms >= 0),
  error_code VARCHAR(100),
  created_by CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='模型调用的输入证据引用、用量、成本和结果状态。';
CREATE INDEX idx_platform_model_calls_tenant_updated ON platform_model_calls (tenant_id, updated_at, model_call_id);
