CREATE UNIQUE INDEX uq_platform_script_version_key ON platform_acquisition_script_versions (tenant_id, script_version_key);
CREATE UNIQUE INDEX uq_platform_acquisition_script_versions ON platform_acquisition_script_versions (acquisition_script_id, version_no);

CREATE TABLE platform_data_asset_versions (
