CREATE UNIQUE INDEX uq_platform_source_systems_code ON platform_source_systems (tenant_id, source_code);

CREATE TABLE platform_memory_evidence (
  memory_evidence_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
