CREATE UNIQUE INDEX uq_platform_memory_evidence ON platform_memory_evidence (memory_id, evidence_type, evidence_id);

CREATE TABLE platform_memory_reviews (
  memory_review_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
