CREATE INDEX idx_platform_analysis_experiences_status ON platform_analysis_experiences (tenant_id, status);

CREATE TABLE platform_analysis_steps (
  analysis_step_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  tenant_id CHAR(36) NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  analysis_task_id CHAR(36) NOT NULL REFERENCES platform_analysis_tasks(analysis_task_id) ON DELETE CASCADE,
  step_code VARCHAR(120) NOT NULL,
