CREATE TABLE platform_evaluations (
  evaluation_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  tenant_id CHAR(36) NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  analysis_task_id CHAR(36) NOT NULL REFERENCES platform_analysis_tasks(analysis_task_id) ON DELETE CASCADE,
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision > 0),
  evaluation_type VARCHAR(40) NOT NULL CHECK (evaluation_type IN ('sql_data_match','metric_correctness','faithfulness','permission','freshness','visualization','overall')),
  status VARCHAR(24) NOT NULL CHECK (status IN ('passed','warning','failed','error')),
  score NUMERIC(7,4) CHECK (score BETWEEN 0 AND 1),
  checks JSON NOT NULL,
  evaluator_type VARCHAR(16) NOT NULL CHECK (evaluator_type IN ('deterministic','model','human')),
  evaluator_version VARCHAR(160) NOT NULL,
  evaluated_artifact_hash CHAR(64) NOT NULL,
  evaluated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  created_by CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='对最终 SQL、数据、图表、结论和权限的质量评审。';
CREATE INDEX idx_platform_evaluations_tenant_updated ON platform_evaluations (tenant_id, updated_at, evaluation_id);
