CREATE TABLE platform_alert_events (
  alert_event_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  tenant_id CHAR(36) NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  alert_rule_id CHAR(36) NOT NULL REFERENCES platform_alert_rules(alert_rule_id) ON DELETE RESTRICT,
  dedupe_key VARCHAR(300) NOT NULL,
  severity VARCHAR(16) NOT NULL,
  status VARCHAR(24) NOT NULL DEFAULT 'open' CHECK (status IN ('open','acknowledged','resolved','suppressed')),
  resource_type VARCHAR(40) NOT NULL,
  resource_id CHAR(36),
  summary TEXT NOT NULL,
  evidence JSON NOT NULL,
  first_seen_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  last_seen_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  occurrence_count INTEGER NOT NULL DEFAULT 1 CHECK (occurrence_count > 0),
  acknowledged_by CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  resolved_at DATETIME(6),
  created_by CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='告警规则命中、去重、确认、解决和证据。';
CREATE INDEX idx_platform_alert_events_tenant_updated ON platform_alert_events (tenant_id, updated_at, alert_event_id);
CREATE INDEX idx_platform_alert_events_open ON platform_alert_events (tenant_id, status, severity, last_seen_at);
CREATE INDEX idx_platform_alert_events_dedupe ON platform_alert_events (tenant_id, alert_rule_id, dedupe_key, last_seen_at);

CREATE TABLE platform_notification_deliveries (
  delivery_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  tenant_id CHAR(36) NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  delivery_key VARCHAR(160) NOT NULL,
  subscription_id CHAR(36) REFERENCES platform_subscriptions(subscription_id) ON DELETE SET NULL,
  outbox_event_id CHAR(36) NOT NULL REFERENCES platform_outbox_events(outbox_event_id) ON DELETE RESTRICT,
  recipient_user_id CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  channel VARCHAR(24) NOT NULL CHECK (channel IN ('in_app','email','feishu','wecom','sms','webhook')),
  template_code VARCHAR(160) NOT NULL,
  payload_ref JSON NOT NULL,
  idempotency_key VARCHAR(200) NOT NULL,
  status VARCHAR(24) NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','sending','accepted','delivered','failed','bounced','cancelled','suppressed','dead_letter')),
  provider_message_id VARCHAR(300),
  attempt_count INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
  next_attempt_at DATETIME(6),
  accepted_at DATETIME(6),
  delivered_at DATETIME(6),
  error_code VARCHAR(100),
  created_by CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='每条通知的真实渠道投递、回执和重试。';
CREATE INDEX idx_platform_notification_deliveries_tenant_updated ON platform_notification_deliveries (tenant_id, updated_at, delivery_id);
CREATE UNIQUE INDEX uq_platform_notification_delivery_key ON platform_notification_deliveries (tenant_id, delivery_key);
CREATE UNIQUE INDEX uq_platform_notification_deliveries ON platform_notification_deliveries (tenant_id, channel, idempotency_key);
CREATE INDEX idx_platform_notification_deliveries_status ON platform_notification_deliveries (tenant_id, status, next_attempt_at);

CREATE TABLE platform_bridge_enrollments (
  enrollment_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  enrollment_key VARCHAR(160) NOT NULL UNIQUE,
  device_code_hash CHAR(64) NOT NULL UNIQUE,
  user_code_hash CHAR(64) NOT NULL UNIQUE,
  channel VARCHAR(32) NOT NULL CHECK (channel IN ('workbuddy','codex','qwork')),
  device_name VARCHAR(160) NOT NULL,
  verifier_hash CHAR(64) NOT NULL,
  status VARCHAR(16) NOT NULL CHECK (status IN ('pending','approved','consumed')),
  tenant_id CHAR(36) REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  user_id CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE CASCADE,
  approved_by CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  expires_at_epoch BIGINT NOT NULL,
  approved_at_epoch BIGINT,
  consumed_at_epoch BIGINT,
  binding_id CHAR(36) REFERENCES platform_bridge_bindings(binding_id) ON DELETE SET NULL,
  created_at_epoch BIGINT NOT NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='十分钟内有效、只能领取一次的 Bridge 设备授权事务。';
CREATE INDEX idx_platform_bridge_enrollments_expiry ON platform_bridge_enrollments (status, expires_at_epoch);

CREATE TABLE platform_analysis_threads (
  thread_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  tenant_id CHAR(36) NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  workspace_id CHAR(36) NOT NULL REFERENCES platform_analysis_workspaces(workspace_id) ON DELETE CASCADE,
  parent_thread_id CHAR(36) REFERENCES platform_analysis_threads(thread_id) ON DELETE RESTRICT,
  root_thread_id CHAR(36) REFERENCES platform_analysis_threads(thread_id) ON DELETE RESTRICT,
  title VARCHAR(240) NOT NULL DEFAULT '',
  anchor JSON NOT NULL DEFAULT (JSON_OBJECT()),
  status VARCHAR(24) NOT NULL DEFAULT 'active' CHECK (status IN ('active','merged','archived')),
  merged_into_thread_id CHAR(36) REFERENCES platform_analysis_threads(thread_id) ON DELETE RESTRICT,
  created_by CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='总体分析及图表、指标、机构或数据点的分支线程。';
CREATE INDEX idx_platform_analysis_threads_tenant_updated ON platform_analysis_threads (tenant_id, updated_at, thread_id);
CREATE INDEX idx_platform_analysis_threads_workspace ON platform_analysis_threads (tenant_id, workspace_id, updated_at);
CREATE INDEX idx_platform_analysis_threads_parent ON platform_analysis_threads (workspace_id, parent_thread_id);

CREATE TABLE platform_agent_group_members (
  agent_group_id CHAR(36) NOT NULL REFERENCES platform_agent_groups(agent_group_id) ON DELETE CASCADE,
  agent_id CHAR(36) NOT NULL REFERENCES platform_agents(agent_id) ON DELETE RESTRICT,
  stage_code VARCHAR(100) NOT NULL,
  sequence_no INTEGER NOT NULL CHECK (sequence_no >= 0),
  is_required BOOLEAN NOT NULL DEFAULT true,
  gate_config JSON NOT NULL DEFAULT (JSON_OBJECT()),
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (agent_group_id, agent_id, stage_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Agent 在编排组中的顺序、职责和门禁。';
CREATE INDEX idx_platform_agent_group_members_order ON platform_agent_group_members (agent_group_id, sequence_no);

CREATE TABLE platform_dataset_fields (
  field_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  tenant_id CHAR(36) NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  dataset_id CHAR(36) NOT NULL REFERENCES platform_datasets(dataset_id) ON DELETE CASCADE,
  field_code VARCHAR(200) NOT NULL,
  field_name VARCHAR(300) NOT NULL,
  ordinal_position INTEGER NOT NULL CHECK (ordinal_position > 0),
  physical_type VARCHAR(120) NOT NULL,
  semantic_type VARCHAR(64),
  is_nullable BOOLEAN NOT NULL DEFAULT true,
  is_dimension BOOLEAN NOT NULL DEFAULT false,
  is_measure BOOLEAN NOT NULL DEFAULT false,
  classification VARCHAR(24) NOT NULL DEFAULT 'internal',
  masking_policy JSON NOT NULL DEFAULT (JSON_OBJECT()),
  metadata JSON NOT NULL DEFAULT (JSON_OBJECT()),
  created_by CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='数据集字段、类型、语义、权限和敏感分类。';
CREATE INDEX idx_platform_dataset_fields_tenant_updated ON platform_dataset_fields (tenant_id, updated_at, field_id);
CREATE UNIQUE INDEX uq_platform_dataset_fields_code ON platform_dataset_fields (dataset_id, field_code);
CREATE INDEX idx_platform_dataset_fields_semantic ON platform_dataset_fields (tenant_id, semantic_type);

CREATE TABLE platform_topic_table_sources (
  topic_table_id CHAR(36) NOT NULL REFERENCES platform_topic_tables(topic_table_id) ON DELETE CASCADE,
  dataset_id CHAR(36) NOT NULL REFERENCES platform_datasets(dataset_id) ON DELETE RESTRICT,
  source_alias VARCHAR(160) NOT NULL,
  join_role VARCHAR(32) NOT NULL DEFAULT 'primary' CHECK (join_role IN ('primary','lookup','bridge')),
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (topic_table_id, dataset_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='主题表依赖的数据集及连接版本。';

CREATE TABLE platform_acquisition_jobs (
  acquisition_job_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  tenant_id CHAR(36) NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  job_key VARCHAR(160) NOT NULL,
  job_code VARCHAR(160) NOT NULL,
  job_name VARCHAR(300) NOT NULL,
  source_system_id CHAR(36) NOT NULL REFERENCES platform_source_systems(source_system_id) ON DELETE RESTRICT,
  script_version_id CHAR(36) NOT NULL REFERENCES platform_acquisition_script_versions(script_version_id) ON DELETE RESTRICT,
  connection_id CHAR(36) NOT NULL REFERENCES platform_data_connections(connection_id) ON DELETE RESTRICT,
  target_dataset_id CHAR(36) REFERENCES platform_datasets(dataset_id) ON DELETE RESTRICT,
  topic_table_id CHAR(36) REFERENCES platform_topic_tables(topic_table_id) ON DELETE SET NULL,
  trigger_type VARCHAR(24) NOT NULL CHECK (trigger_type IN ('manual','schedule','event')),
  schedule_expression VARCHAR(200),
  execution_mode VARCHAR(16) NOT NULL CHECK (execution_mode IN ('realtime','offline')),
  job_config JSON NOT NULL DEFAULT (JSON_OBJECT()),
  status VARCHAR(24) NOT NULL DEFAULT 'active' CHECK (status IN ('active','paused','disabled')),
  next_run_at DATETIME(6),
  owner_user_id CHAR(36) NOT NULL REFERENCES platform_user_profiles(user_id) ON DELETE RESTRICT,
  created_by CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='实时/离线/API/文件数据获取任务定义。';
CREATE INDEX idx_platform_acquisition_jobs_tenant_updated ON platform_acquisition_jobs (tenant_id, updated_at, acquisition_job_id);
CREATE UNIQUE INDEX uq_platform_acquisition_jobs_key ON platform_acquisition_jobs (tenant_id, job_key);
CREATE UNIQUE INDEX uq_platform_acquisition_jobs_code ON platform_acquisition_jobs (tenant_id, job_code);
CREATE INDEX idx_platform_acquisition_jobs_due ON platform_acquisition_jobs (status, next_run_at);

CREATE TABLE platform_data_quality_rules (
  quality_rule_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  tenant_id CHAR(36) NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  dataset_id CHAR(36) NOT NULL REFERENCES platform_datasets(dataset_id) ON DELETE CASCADE,
  rule_code VARCHAR(160) NOT NULL,
  rule_name VARCHAR(300) NOT NULL,
  rule_type VARCHAR(32) NOT NULL CHECK (rule_type IN ('freshness','completeness','validity','uniqueness','consistency','custom')),
  rule_expression JSON NOT NULL,
  severity VARCHAR(16) NOT NULL CHECK (severity IN ('info','warning','error','critical')),
  blocking BOOLEAN NOT NULL DEFAULT false,
  status VARCHAR(24) NOT NULL DEFAULT 'active' CHECK (status IN ('draft','active','disabled')),
  created_by CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='数据完整性、准确性、一致性和新鲜度规则。';
CREATE INDEX idx_platform_data_quality_rules_tenant_updated ON platform_data_quality_rules (tenant_id, updated_at, quality_rule_id);
CREATE UNIQUE INDEX uq_platform_data_quality_rules_code ON platform_data_quality_rules (tenant_id, dataset_id, rule_code);

CREATE TABLE platform_data_asset_reviews (
  asset_review_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  tenant_id CHAR(36) NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  asset_version_id CHAR(36) NOT NULL REFERENCES platform_data_asset_versions(asset_version_id) ON DELETE CASCADE,
  decision VARCHAR(24) NOT NULL CHECK (decision IN ('approved','rejected','changes_required')),
  reviewer_user_id CHAR(36) NOT NULL REFERENCES platform_user_profiles(user_id) ON DELETE RESTRICT,
  comments VARCHAR(4096) NOT NULL DEFAULT '',
  decided_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  created_by CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='数据资产版本的追加式人工复核决策。';
CREATE INDEX idx_platform_data_asset_reviews_tenant_updated ON platform_data_asset_reviews (tenant_id, updated_at, asset_review_id);
CREATE INDEX idx_platform_data_asset_reviews_version ON platform_data_asset_reviews (tenant_id, asset_version_id, decided_at);

CREATE TABLE platform_market_sources (
  market_source_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  tenant_id CHAR(36) NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  market_source_key VARCHAR(160) NOT NULL,
  source_system_id CHAR(36) NOT NULL REFERENCES platform_source_systems(source_system_id) ON DELETE RESTRICT,
  source_url TEXT,
  publisher VARCHAR(300) NOT NULL,
  acquisition_method VARCHAR(32) NOT NULL CHECK (acquisition_method IN ('api','database','file','licensed_feed','manual_review')),
  license_type VARCHAR(100),
  reliability_score NUMERIC(7,4) CHECK (reliability_score BETWEEN 0 AND 1),
  status VARCHAR(24) NOT NULL DEFAULT 'active' CHECK (status IN ('active','paused','expired','disabled')),
  created_by CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='市场数据来源、许可、抓取方式和可信度。';
CREATE INDEX idx_platform_market_sources_tenant_updated ON platform_market_sources (tenant_id, updated_at, market_source_id);
CREATE UNIQUE INDEX uq_platform_market_source_key ON platform_market_sources (tenant_id, market_source_key);
CREATE INDEX idx_platform_market_sources_system ON platform_market_sources (tenant_id, source_system_id, status);

CREATE TABLE platform_operating_system_mappings (
  mapping_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  tenant_id CHAR(36) NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  source_system_id CHAR(36) NOT NULL REFERENCES platform_source_systems(source_system_id) ON DELETE CASCADE,
  mapping_type VARCHAR(32) NOT NULL CHECK (mapping_type IN ('org','customer','metric','dataset','topic_table','product')),
  external_code VARCHAR(300) NOT NULL,
  platform_entity_type VARCHAR(40) NOT NULL,
  platform_entity_id CHAR(36) NOT NULL,
  effective_from DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  effective_to DATETIME(6),
  mapping_status VARCHAR(24) NOT NULL DEFAULT 'active' CHECK (mapping_status IN ('pending','active','conflict','expired')),
  created_by CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='毓数/智能运营系统与平台机构、客户、指标、主题表编码映射。';
CREATE INDEX idx_platform_operating_system_mappings_tenant_updated ON platform_operating_system_mappings (tenant_id, updated_at, mapping_id);
CREATE UNIQUE INDEX uq_platform_operating_mappings ON platform_operating_system_mappings (tenant_id, source_system_id, mapping_type, external_code, effective_from);
CREATE INDEX idx_platform_operating_mappings_target ON platform_operating_system_mappings (tenant_id, platform_entity_type, platform_entity_id);

CREATE TABLE platform_knowledge_versions (
  knowledge_version_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  tenant_id CHAR(36) NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  version_key VARCHAR(160) NOT NULL,
  document_id CHAR(36) NOT NULL REFERENCES platform_knowledge_documents(document_id) ON DELETE CASCADE,
  version_no INTEGER NOT NULL CHECK (version_no > 0),
  source_attachment_id CHAR(36) REFERENCES platform_file_attachments(attachment_id) ON DELETE RESTRICT,
  content_artifact_id CHAR(36) REFERENCES platform_data_artifacts(artifact_id) ON DELETE RESTRICT,
  content_hash CHAR(64) NOT NULL,
  language VARCHAR(32) NOT NULL DEFAULT 'zh-CN',
  parser_name VARCHAR(160),
  processing_status VARCHAR(24) NOT NULL DEFAULT 'pending' CHECK (processing_status IN ('pending','scanning','parsing','indexing','ready','failed')),
  published_at DATETIME(6),
  reviewed_by CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_by CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='不可变知识正文版本及对象存储来源。';
CREATE INDEX idx_platform_knowledge_versions_tenant_updated ON platform_knowledge_versions (tenant_id, updated_at, knowledge_version_id);
CREATE UNIQUE INDEX uq_platform_knowledge_version_key ON platform_knowledge_versions (tenant_id, version_key);
CREATE UNIQUE INDEX uq_platform_knowledge_versions ON platform_knowledge_versions (document_id, version_no);

CREATE TABLE platform_analysis_queries (
  analysis_query_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  tenant_id CHAR(36) NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  analysis_task_id CHAR(36) NOT NULL REFERENCES platform_analysis_tasks(analysis_task_id) ON DELETE CASCADE,
  analysis_step_id CHAR(36) REFERENCES platform_analysis_steps(analysis_step_id) ON DELETE SET NULL,
  connection_version_id CHAR(36) NOT NULL REFERENCES platform_connection_versions(connection_version_id) ON DELETE RESTRICT,
  dataset_id CHAR(36) NOT NULL REFERENCES platform_datasets(dataset_id) ON DELETE RESTRICT,
  query_revision INTEGER NOT NULL CHECK (query_revision > 0),
  compiled_sql TEXT NOT NULL,
  sql_hash CHAR(64) NOT NULL,
  parameters JSON NOT NULL DEFAULT (JSON_OBJECT()),
  policy_snapshot JSON NOT NULL,
  status VARCHAR(24) NOT NULL CHECK (status IN ('queued','running','succeeded','failed','cancelled')),
  result_artifact_id CHAR(36) REFERENCES platform_data_artifacts(artifact_id) ON DELETE RESTRICT,
  result_hash CHAR(64),
  row_count BIGINT CHECK (row_count >= 0),
  summary JSON NOT NULL DEFAULT (JSON_OBJECT()),
  started_at DATETIME(6),
  finished_at DATETIME(6),
  created_by CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='经权限编译并真实执行的 SQL/语义查询和结果摘要。';
CREATE INDEX idx_platform_analysis_queries_tenant_updated ON platform_analysis_queries (tenant_id, updated_at, analysis_query_id);
CREATE UNIQUE INDEX uq_platform_analysis_queries_revision ON platform_analysis_queries (analysis_task_id, query_revision);
CREATE INDEX idx_platform_analysis_queries_hash ON platform_analysis_queries (tenant_id, sql_hash, created_at);

CREATE TABLE platform_analysis_artifacts (
  analysis_artifact_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  tenant_id CHAR(36) NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  analysis_task_id CHAR(36) NOT NULL REFERENCES platform_analysis_tasks(analysis_task_id) ON DELETE CASCADE,
  analysis_step_id CHAR(36) REFERENCES platform_analysis_steps(analysis_step_id) ON DELETE SET NULL,
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision > 0),
  artifact_type VARCHAR(32) NOT NULL CHECK (artifact_type IN ('plan','python_script','chart','table','conclusion','model_draft','review','export')),
  execution_status VARCHAR(24) NOT NULL CHECK (execution_status IN ('draft','executed','verified','rejected')),
  content JSON NOT NULL DEFAULT (JSON_OBJECT()),
  data_artifact_id CHAR(36) REFERENCES platform_data_artifacts(artifact_id) ON DELETE RESTRICT,
  content_hash CHAR(64) NOT NULL,
  parent_artifact_id CHAR(36) REFERENCES platform_analysis_artifacts(analysis_artifact_id) ON DELETE SET NULL,
  created_by CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='脚本、图表、表格、草稿和结论等分析产物。';
CREATE INDEX idx_platform_analysis_artifacts_tenant_updated ON platform_analysis_artifacts (tenant_id, updated_at, analysis_artifact_id);
CREATE INDEX idx_platform_analysis_artifacts_task ON platform_analysis_artifacts (analysis_task_id, artifact_type, created_at);
CREATE UNIQUE INDEX uq_platform_analysis_artifacts_revision ON platform_analysis_artifacts (analysis_task_id, revision, artifact_type);

CREATE TABLE platform_weekly_report_versions (
  report_version_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  tenant_id CHAR(36) NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  report_version_key VARCHAR(160) NOT NULL,
  report_id CHAR(36) NOT NULL REFERENCES platform_reports(report_id) ON DELETE CASCADE,
  version_no INTEGER NOT NULL CHECK (version_no > 0),
  parent_version_id CHAR(36) REFERENCES platform_weekly_report_versions(report_version_id) ON DELETE SET NULL,
  period_start DATE NOT NULL,
  period_end DATE NOT NULL,
  status VARCHAR(24) NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','submitted','review','published','withdrawn','archived')),
  version_checksum CHAR(64) NOT NULL,
  data_snapshot_at DATETIME(6) NOT NULL,
  submitted_at DATETIME(6),
