) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='从可发布报告证据生成的不可变日报邮件产物及投递汇总。';
CREATE INDEX idx_platform_daily_report_runs_tenant_updated ON platform_daily_report_runs (tenant_id, updated_at, daily_report_run_id);
CREATE UNIQUE INDEX uq_platform_daily_report_run_key ON platform_daily_report_runs (tenant_id, daily_report_run_key);
CREATE UNIQUE INDEX uq_platform_daily_report_runs_content ON platform_daily_report_runs (tenant_id, owner_user_id, report_date, content_hash);
CREATE INDEX idx_platform_daily_report_runs_status ON platform_daily_report_runs (tenant_id, status, report_date);

CREATE TABLE platform_acquisition_repair_proposals (
  repair_proposal_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  tenant_id CHAR(36) NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  repair_proposal_key VARCHAR(160) NOT NULL,
  acquisition_run_id CHAR(36) NOT NULL REFERENCES platform_acquisition_job_runs(acquisition_run_id) ON DELETE CASCADE,
  failed_script_version_id CHAR(36) NOT NULL REFERENCES platform_acquisition_script_versions(script_version_id) ON DELETE RESTRICT,
  diagnosis JSON NOT NULL,
  generation_method VARCHAR(24) NOT NULL CHECK (generation_method IN ('deterministic','llm','manual')),
  candidate_source_code TEXT,
  candidate_hash CHAR(64),
  model_call_id CHAR(36) REFERENCES platform_model_calls(model_call_id) ON DELETE SET NULL,
  review_status VARCHAR(24) NOT NULL DEFAULT 'pending' CHECK (review_status IN ('pending','approved','rejected','applied','superseded')),
  reviewed_by CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  reviewed_at DATETIME(6),
  applied_script_version_id CHAR(36) REFERENCES platform_acquisition_script_versions(script_version_id) ON DELETE SET NULL,
  created_by CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='采集失败后的受控诊断与脚本修复候选，必须评审后才能形成新版本。';
CREATE INDEX idx_platform_acquisition_repair_proposals_tenant_updated ON platform_acquisition_repair_proposals (tenant_id, updated_at, repair_proposal_id);
CREATE UNIQUE INDEX uq_platform_repair_proposal_key ON platform_acquisition_repair_proposals (tenant_id, repair_proposal_key);
CREATE INDEX idx_platform_acquisition_repairs_run ON platform_acquisition_repair_proposals (tenant_id, acquisition_run_id, created_at);
CREATE INDEX idx_platform_acquisition_repairs_review ON platform_acquisition_repair_proposals (tenant_id, review_status, created_at);

CREATE TABLE platform_dataset_partitions (
  partition_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  tenant_id CHAR(36) NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  partition_code VARCHAR(160) NOT NULL,
  dataset_id CHAR(36) NOT NULL REFERENCES platform_datasets(dataset_id) ON DELETE CASCADE,
  topic_table_id CHAR(36) REFERENCES platform_topic_tables(topic_table_id) ON DELETE SET NULL,
  org_unit_id CHAR(36) REFERENCES platform_org_units(org_unit_id) ON DELETE SET NULL,
  partition_key JSON NOT NULL,
  partition_hash CHAR(64) NOT NULL,
  artifact_id CHAR(36) REFERENCES platform_data_artifacts(artifact_id) ON DELETE RESTRICT,
  source_version VARCHAR(200),
  snapshot_at DATETIME(6) NOT NULL,
  watermark_at DATETIME(6),
  row_count BIGINT CHECK (row_count >= 0),
  data_hash CHAR(64),
  freshness_status VARCHAR(24) NOT NULL CHECK (freshness_status IN ('fresh','stale','unknown','blocked')),
  acquisition_run_id CHAR(36) NOT NULL REFERENCES platform_acquisition_job_runs(acquisition_run_id) ON DELETE RESTRICT,
  created_by CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='数据集分区、快照、新鲜度和对应 Artifact。';
CREATE INDEX idx_platform_dataset_partitions_tenant_updated ON platform_dataset_partitions (tenant_id, updated_at, partition_id);
CREATE UNIQUE INDEX uq_platform_partition_code ON platform_dataset_partitions (tenant_id, partition_code);
CREATE UNIQUE INDEX uq_platform_dataset_partitions ON platform_dataset_partitions (dataset_id, partition_hash, snapshot_at);
CREATE INDEX idx_platform_dataset_partitions_latest ON platform_dataset_partitions (tenant_id, dataset_id, org_unit_id, snapshot_at);

CREATE TABLE platform_market_monitoring_events (
  market_event_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  tenant_id CHAR(36) NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  market_event_key VARCHAR(160) NOT NULL,
  market_rule_id CHAR(36) NOT NULL REFERENCES platform_market_monitoring_rules(market_rule_id) ON DELETE RESTRICT,
  market_entity_id CHAR(36) NOT NULL REFERENCES platform_market_entities(market_entity_id) ON DELETE RESTRICT,
  observation_id CHAR(36) REFERENCES platform_market_observations(market_observation_id) ON DELETE SET NULL,
  severity VARCHAR(16) NOT NULL,
  status VARCHAR(24) NOT NULL DEFAULT 'open' CHECK (status IN ('open','acknowledged','resolved','suppressed')),
  event_summary TEXT NOT NULL,
  evidence JSON NOT NULL,
  detected_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  resolved_at DATETIME(6),
  acknowledged_by CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_by CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='市场规则命中事件、证据和处置状态。';
CREATE INDEX idx_platform_market_monitoring_events_tenant_updated ON platform_market_monitoring_events (tenant_id, updated_at, market_event_id);
CREATE UNIQUE INDEX uq_platform_market_event_key ON platform_market_monitoring_events (tenant_id, market_event_key);
CREATE UNIQUE INDEX uq_platform_market_event_observation ON platform_market_monitoring_events (market_rule_id, observation_id);
CREATE INDEX idx_platform_market_events_open ON platform_market_monitoring_events (tenant_id, status, severity, detected_at);

CREATE TABLE platform_knowledge_citations (
  citation_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  tenant_id CHAR(36) NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  citation_key VARCHAR(160) NOT NULL,
  chunk_id CHAR(36) NOT NULL REFERENCES platform_knowledge_chunks(chunk_id) ON DELETE RESTRICT,
  resource_type VARCHAR(40) NOT NULL,
  resource_id VARCHAR(300) NOT NULL,
  quote_hash CHAR(64) NOT NULL,
  locator JSON NOT NULL DEFAULT (JSON_OBJECT()),
  relevance_score NUMERIC(7,4) CHECK (relevance_score BETWEEN 0 AND 1),
  created_by CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='分析结论、报告块对知识分块的可验证引用。';
CREATE INDEX idx_platform_knowledge_citations_tenant_updated ON platform_knowledge_citations (tenant_id, updated_at, citation_id);
CREATE UNIQUE INDEX uq_platform_knowledge_citation ON platform_knowledge_citations (tenant_id, chunk_id, resource_type, resource_id);
CREATE INDEX idx_platform_knowledge_citations_resource ON platform_knowledge_citations (tenant_id, resource_type, resource_id);

CREATE TABLE platform_report_block_sources (
  report_block_id CHAR(36) NOT NULL REFERENCES platform_report_blocks(report_block_id) ON DELETE CASCADE,
  source_type VARCHAR(32) NOT NULL CHECK (source_type IN ('analysis_task','analysis_query','analysis_artifact','partition','knowledge','market_event')),
  source_id CHAR(36) NOT NULL,
  source_hash CHAR(64) NOT NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (report_block_id, source_type, source_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='报告块与分析、查询、数据分区和知识证据之间的来源关系。';
CREATE INDEX idx_platform_report_block_sources_source ON platform_report_block_sources (source_type, source_id);

CREATE TABLE platform_report_comments (
  comment_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  tenant_id CHAR(36) NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  comment_key VARCHAR(160) NOT NULL,
  client_request_id VARCHAR(200),
  report_id CHAR(36) NOT NULL REFERENCES platform_reports(report_id) ON DELETE CASCADE,
  report_version_id CHAR(36) REFERENCES platform_weekly_report_versions(report_version_id) ON DELETE CASCADE,
  report_block_id CHAR(36) REFERENCES platform_report_blocks(report_block_id) ON DELETE CASCADE,
  author_user_id CHAR(36) NOT NULL REFERENCES platform_user_profiles(user_id) ON DELETE RESTRICT,
  comment_body TEXT NOT NULL,
  anchor JSON NOT NULL DEFAULT (JSON_OBJECT()),
  status VARCHAR(24) NOT NULL DEFAULT 'open' CHECK (status IN ('open','resolved','reopened','deleted')),
  resolved_by CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  resolved_at DATETIME(6),
  created_by CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='报告版本或块上的单条评论和解决状态。';
CREATE INDEX idx_platform_report_comments_tenant_updated ON platform_report_comments (tenant_id, updated_at, comment_id);
CREATE UNIQUE INDEX uq_platform_report_comment_key ON platform_report_comments (tenant_id, comment_key);
CREATE UNIQUE INDEX uq_platform_report_comment_request ON platform_report_comments (tenant_id, report_id, client_request_id);
CREATE INDEX idx_platform_report_comments_report ON platform_report_comments (report_id, status, created_at);
CREATE INDEX idx_platform_report_comments_version ON platform_report_comments (report_version_id, status, created_at);

CREATE TABLE platform_data_quality_results (
  quality_result_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  tenant_id CHAR(36) NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  quality_result_key VARCHAR(160) NOT NULL,
  quality_rule_id CHAR(36) NOT NULL REFERENCES platform_data_quality_rules(quality_rule_id) ON DELETE RESTRICT,
  partition_id CHAR(36) REFERENCES platform_dataset_partitions(partition_id) ON DELETE CASCADE,
  acquisition_run_id CHAR(36) NOT NULL REFERENCES platform_acquisition_job_runs(acquisition_run_id) ON DELETE CASCADE,
  status VARCHAR(24) NOT NULL CHECK (status IN ('passed','warning','failed','error')),
  score NUMERIC(7,4) CHECK (score BETWEEN 0 AND 1),
  observed_value JSON NOT NULL DEFAULT (JSON_OBJECT()),
  threshold JSON NOT NULL DEFAULT (JSON_OBJECT()),
  sample_artifact_id CHAR(36) REFERENCES platform_data_artifacts(artifact_id) ON DELETE SET NULL,
  evaluated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  created_by CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='质量规则对指定分区/快照的执行结果。';
CREATE INDEX idx_platform_data_quality_results_tenant_updated ON platform_data_quality_results (tenant_id, updated_at, quality_result_id);
CREATE UNIQUE INDEX uq_platform_quality_result_key ON platform_data_quality_results (tenant_id, quality_result_key);
CREATE INDEX idx_platform_data_quality_results_partition ON platform_data_quality_results (tenant_id, partition_id, status);
CREATE INDEX idx_platform_data_quality_results_run ON platform_data_quality_results (tenant_id, acquisition_run_id, evaluated_at);

CREATE TABLE platform_report_comment_replies (
  reply_id CHAR(36) PRIMARY KEY DEFAULT (UUID()),
  tenant_id CHAR(36) NOT NULL REFERENCES platform_tenants(tenant_id) ON DELETE CASCADE,
  reply_key VARCHAR(160) NOT NULL,
  client_request_id VARCHAR(200),
