  created_by CHAR(36) REFERENCES platform_user_profiles(user_id) ON DELETE SET NULL,
  created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  lock_version BIGINT NOT NULL DEFAULT 0 CHECK (lock_version >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='评论线程中的单条回复。';
CREATE INDEX idx_platform_report_comment_replies_tenant_updated ON platform_report_comment_replies (tenant_id, updated_at, reply_id);
CREATE UNIQUE INDEX uq_platform_report_reply_key ON platform_report_comment_replies (tenant_id, reply_key);
CREATE UNIQUE INDEX uq_platform_report_reply_request ON platform_report_comment_replies (tenant_id, comment_id, client_request_id);
CREATE INDEX idx_platform_report_comment_replies ON platform_report_comment_replies (comment_id, created_at);

